local GardenLineMaker = {}
local PRODUCTS = {
    iron_gardenline = { name = "Železni vrtna vrvica", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vrtna vrvica za vrtnarje." },
    bronze_gardenline = { name = "Bronast vrtna vrvica", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vrtna vrvica za vrtnarje." },
    silver_gardenline = { name = "Srebrn vrtna vrvica", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vrtna vrvica za vrtnarje." },
    gilded_gardenline = { name = "Pozlačen vrtna vrvica", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vrtna vrvica za vrtnarje." },
    jewel_set_gardenline = { name = "Draguljast vrtna vrvica", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vrtna vrvica za vrtnarje." },
    royal_sovereign_gardenline = { name = "Kraljevski suveren vrtna vrvica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vrtna vrvica z biseri za krono." },
}
local BUILDINGS = {
    gardenline_workshop = { name = "Gardenline delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    gardenline_house = { name = "Gardenline hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_gardenline_atelier = { name = "Mojstrski gardenline atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_gardenline_palace = { name = "Suverena gardenline palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenLineMaker.ironStock=12; GardenLineMaker.bronzeStock=10; GardenLineMaker.woodStock=14; GardenLineMaker.leatherStock=10; GardenLineMaker.silverStock=8; GardenLineMaker.goldStock=6; GardenLineMaker.jewelStock=4; GardenLineMaker.pearlStock=4
GardenLineMaker.productStock = {}; GardenLineMaker.buildings = {}; GardenLineMaker.maker = nil; GardenLineMaker.activeMaking = {}; GardenLineMaker.totalProducts = 0; GardenLineMaker.dayTimer = 0
function GardenLineMaker.init() GardenLineMaker.ironStock=12; GardenLineMaker.bronzeStock=10; GardenLineMaker.woodStock=14; GardenLineMaker.leatherStock=10; GardenLineMaker.silverStock=8; GardenLineMaker.goldStock=6; GardenLineMaker.jewelStock=4; GardenLineMaker.pearlStock=4; GardenLineMaker.productStock={}; GardenLineMaker.buildings={}; GardenLineMaker.maker=nil; GardenLineMaker.activeMaking={}; GardenLineMaker.totalProducts=0; GardenLineMaker.dayTimer=0; print("[GardenLineMaker] Royal Garden Line Maker System initialized (6 products, 4 buildings)") end
function GardenLineMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenLineMaker.maker={name=n or ("Vrvicar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrvicar najet: %s (spretnost: %d)",GardenLineMaker.maker.name,s),"success") end; return true end
function GardenLineMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenLineMaker.build(id) local ok,e=GardenLineMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenLineMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenLineMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenLineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenLineMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenLineMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenLineMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenLineMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenLineMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenLineMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenLineMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenLineMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenLineMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenLineMaker.buildings==0 then return false,"Potrebna vrvična delavnica" end; if not GardenLineMaker.maker then return false,"Potreben vrvicar" end; return true end
function GardenLineMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenLineMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenLineMaker.ironStock=GardenLineMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenLineMaker.bronzeStock=GardenLineMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenLineMaker.woodStock=GardenLineMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenLineMaker.leatherStock=GardenLineMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenLineMaker.silverStock=GardenLineMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenLineMaker.goldStock=GardenLineMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenLineMaker.jewelStock=GardenLineMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenLineMaker.pearlStock=GardenLineMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenLineMaker.maker then t=math.max(1,t-math.floor(GardenLineMaker.maker.skill/13)) end; table.insert(GardenLineMaker.activeMaking,{id="gardenline_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenLineMaker.completeMaking(m) local q=1.0+(GardenLineMaker.getQualityBonus()/100); if GardenLineMaker.maker then q=q+(GardenLineMaker.maker.skill/140) end; q=math.min(2.5,q); GardenLineMaker.productStock[m.productType]=(GardenLineMaker.productStock[m.productType] or 0)+m.quantity; GardenLineMaker.totalProducts=GardenLineMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenLineMaker.maker then GardenLineMaker.maker.itemsMade=GardenLineMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenLineMaker.maker.skill=math.min(100,GardenLineMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrvica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenline.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenLineMaker.update(dt) if not _G.state then return end; GardenLineMaker.dayTimer=GardenLineMaker.dayTimer+dt; if GardenLineMaker.dayTimer>=30 then GardenLineMaker.dayTimer=0; for i=#GardenLineMaker.activeMaking,1,-1 do local m=GardenLineMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenLineMaker.completeMaking(m); table.remove(GardenLineMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenLineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenLineMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenLineMaker.getStats() return {ironStock=GardenLineMaker.ironStock,bronzeStock=GardenLineMaker.bronzeStock,woodStock=GardenLineMaker.woodStock,leatherStock=GardenLineMaker.leatherStock,silverStock=GardenLineMaker.silverStock,goldStock=GardenLineMaker.goldStock,jewelStock=GardenLineMaker.jewelStock,pearlStock=GardenLineMaker.pearlStock,productStock=GardenLineMaker.productStock,numBuildings=#GardenLineMaker.buildings,hasMaker=GardenLineMaker.maker~=nil,makerName=GardenLineMaker.maker and GardenLineMaker.maker.name or "—",makerSkill=GardenLineMaker.maker and GardenLineMaker.maker.skill or 0,activeMaking=#GardenLineMaker.activeMaking,totalProducts=GardenLineMaker.totalProducts} end
return GardenLineMaker
